// Writes a CI-only .dev.vars for the e2e job. The file is gitignored and the
// values are fresh per run; nothing here is a real credential.
import { randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";

if (!process.env.CI) {
  // Never clobber a developer's local .dev.vars.
  console.error("scripts/write-ci-dev-vars.mjs only runs in CI (CI is not set)");
  process.exit(1);
}

const secret = () => randomBytes(32).toString("hex");

const lines = [
  "# Generated by scripts/write-ci-dev-vars.mjs. Never commit.",
  `BETTER_AUTH_SECRET=${secret()}`,
  `PASSWORD_PEPPER=${secret()}`,
  `IP_HASH_SALT=${secret()}`,
  "SITE_URL=http://localhost:5173",
  "CDN_URL=http://localhost:5173",
  "R2_BUCKET_NAME=pineboard-assets",
  "ENVIRONMENT=development",
  "ADMIN_EMAILS=admin@example.test",
  "EMAIL_TRANSPORT=log",
  // Cloudflare's public always-pass test keys; siteverify still runs.
  "TURNSTILE_SITE_KEY=1x00000000000000000000AA",
  "TURNSTILE_SECRET=1x0000000000000000000000000000000AA",
  "DEV_RESET_TOKEN=local-dev-reset",
];

writeFileSync(".dev.vars", `${lines.join("\n")}\n`);
console.log("wrote .dev.vars for the e2e job");
